import React, { useState } from 'react';
import ShareModal from './pages/ShareModal';

function App() {
  const [showModal, setShowModal] = useState(true);

  return (
    <div>
      {showModal && (
        <ShareModal
          playlistTitle="Happy Vibes"
          onClose={() => setShowModal(false)}
        />
      )}
    </div>
  );
}

export default App;
